  AND m.brand = v.brand AND m.model = v.model AND m.product_url = v.old_url;

-- Eskimo and Braca serve the same pages over https.
UPDATE materials
SET product_url = regexp_replace(product_url, '^http://', 'https://')
WHERE created_by = 'system-catalogue'
  AND product_url ~ '^http://(www[.]eskimo[.]de|paddles[.]braca-sport[.]com)/';
